const temperature = 31

if (temperature > 30) {
    console.log("Juda issiq, suv iching!")
} else {
    console.log("Havo me'yorida")
}

function getGrade(score: number): string {
    if (score >= 90) {
        return "A'lo (5)"
    } else if (score >= 70) {
        return "Yaxshi (4)"
    } else if (score >= 50) {
        return "Qoniqarli (3)"
    } else {
        return "Qoniqarsiz (2)"
    }
}

console.log(getGrade(95))
console.log(getGrade(72))
console.log(getGrade(50))
console.log(getGrade(31))

type Order = { items: string[]; paid: boolean; address?: string }

function shipOrder(order: Order): string {
    if (order.items.length === 0) return "Xato: savat bo'sh"
    if (!order.paid) return "Xato: to'lov qilinmagan"
    if (!order.address) return "Xato: manzil ko'rsatilmagan"

    return "Buyurtma jo'natildi: " + order.address
}

console.log(shipOrder({ items: [], paid: true }))
console.log(shipOrder({ items: ["kitob"], paid: false }))
console.log(shipOrder({ items: ["kitob"], paid: true, address: "Andijon" }))

function formatId(id: string | number): string {
    if (typeof id === "number") {
        return "#" + id.toString().padStart(5, "0")   // id: number
    }
    return id.toUpperCase()                          // id: string
}

console.log(formatId(42))
console.log(formatId("abc-7"))

function isLeapYear(year: number): boolean {
    if (year % 400 === 0) return true
    if (year % 100 === 0) return false
    return year % 4 === 0
}

for (const year of [2000, 1900, 2024, 2026, 2100]) {
    console.log(year, isLeapYear(year) ? "kabisa yili" : "oddiy yil")
}

function getDiscount(total: number, isMember: boolean): number {
    let discount = 0

    if (total >= 1_000_000) {
        discount = 15
    } else if (total >= 500_000) {
        discount = 10
    } else if (total >= 100_000) {
        discount = 5
    }

    if (isMember) discount += 5

    return Math.min(discount, 20)
}

console.log(getDiscount(50_000, false), "%")
console.log(getDiscount(600_000, false), "%")
console.log(getDiscount(1_200_000, true), "%")

