type Fish = { name: string; swim: () => string }
type Bird = { name: string; fly: () => string }

// "pet is Fish" — funksiya true qaytarsa, TypeScript pet ni Fish deb biladi
function isFish(pet: Fish | Bird): pet is Fish {
    return "swim" in pet
}

function move(pet: Fish | Bird): string {
    if (isFish(pet)) {
        return `${pet.name}: ${pet.swim()}`   // pet: Fish
    }
    return `${pet.name}: ${pet.fly()}`         // pet: Bird
}

