function validate(user: { name: string; age: number; email: string }): string[] {
    const errors: string[] = []
    if (user.name.trim().length < 2) errors.push("Ism juda qisqa")
    if (user.age < 0 || user.age > 120) errors.push("Yosh noto'g'ri")
    if (!user.email.includes("@")) errors.push("Email noto'g'ri")
    return errors
}
