type User = { active: boolean; verified: boolean }

function canLogin(user: User): boolean {
    // O'qish qiyin: if (!(user.active && user.verified)) return false
    // De Morgan: !(A && B) === !A || !B — ikkala yozuv bir xil natija beradi
    if (!user.active || !user.verified) return false
    return true
}

const cases: User[] = [
    { active: true, verified: true },
    { active: true, verified: false },
    { active: false, verified: true },
]
for (const u of cases) {
    const same = !(u.active && u.verified) === (!u.active || !u.verified)
    console.log(canLogin(u), "| ikki yozuv teng:", same)
}

