type Direction = "left" | "right"

function arrow(dir: Direction): string {
    if (dir === "left") {
        return "<-"           // dir: "left"
    }
    // Bu yerda TypeScript dir ni faqat "right" deb biladi
    return "->"               // dir: "right"
}

function step(dir: Direction, x: number): number {
    const delta = dir === "left" ? -1 : 1
    return x + delta
}

console.log(arrow("left"), arrow("right"))
console.log(step("left", 5), step("right", 5))
// arrow("up")   // Xato: Argument of type '"up"' is not assignable to parameter of type 'Direction'

function format(value: string | number | boolean): string {
    const isText = typeof value === "string"     // shartni o'zgaruvchiga saqladik
    const isNum = typeof value === "number"

    if (isText) {
        return value.trim().toUpperCase()         // isText orqali value: string
    }
    if (isNum) {
        return value.toFixed(2)                   // value: number
    }
    return value ? "ha" : "yo'q"                  // qoldi: boolean
}

console.log(format("  salom "))
console.log(format(3.14159))
console.log(format(false))

