type State = "idle" | "loading" | "success" | "error"
type Action = "FETCH" | "RESOLVE" | "REJECT" | "RESET"

function reducer(state: State, action: Action): State {
    switch (state) {
        case "idle":
            return action === "FETCH" ? "loading" : state
        case "loading":
            if (action === "RESOLVE") return "success"
            if (action === "REJECT") return "error"
            return state
        case "success":
        case "error":
            return action === "RESET" ? "idle" : state
    }
}

let state: State = "idle"
for (const action of ["FETCH", "RESOLVE", "RESET", "FETCH", "REJECT"] as Action[]) {
    const next = reducer(state, action)
    console.log(`${state} --${action}--> ${next}`)
    state = next
}

type Shape =
