const handlers: Record<string, (a: number, b: number) => number> = {
    "+": (a, b) => a + b,
    "-": (a, b) => a - b,
    "*": (a, b) => a * b,
    "/": (a, b) => a / b,
}

function calc(expr: string) {
    const [a, op, b] = expr.split(" ")
    const fn = handlers[op]
    return fn ? fn(Number(a), Number(b)) : `noma'lum amal: ${op}`
}

