function merge(a: number[], b: number[]): number[] {
    const out: number[] = []
    let i = 0, j = 0
    while (i < a.length && j < b.length) {   // ikkala massivda ham element bor ekan
        if (a[i] <= b[j]) out.push(a[i++])
        else out.push(b[j++])
    }
    while (i < a.length) out.push(a[i++])   // birining qoldig'i
    while (j < b.length) out.push(b[j++])
    return out
}

