function tokenize(src: string): string[] {
    const tokens: string[] = []
    let i = 0
    while (i < src.length) {
        const ch = src[i]
        if (ch === " ") { i++; continue }                 // bo'shliqni o'tkazib yuborish
        if (ch >= "0" && ch <= "9") {
            let num = ""
            // Ichki while: ketma-ket raqamlarni bitta sonning o'ziga yig'ish
            while (i < src.length && src[i] >= "0" && src[i] <= "9") num += src[i++]
            tokens.push(num)
            continue
        }
        tokens.push(ch)                                   // operator yoki qavs
        i++
    }
    return tokens
}

