const commands = ["add", "add", "stop", "add"]
let count = 0

// Xato: switch ichidagi break faqat switch'dan chiqadi, sikl davom etadi
for (const cmd of commands) {
    switch (cmd) {
        case "add": count++; break
        case "stop": break          // sikl TO'XTAMAYDI
    }
}
console.log("switch break bilan:", count)   // 3 — stop dan keyingi add ham sanaldi

// To'g'ri: label bilan sikldan chiqish
count = 0
loop: for (const cmd of commands) {
    switch (cmd) {
        case "add": count++; break
        case "stop": break loop     // sikldan chiqadi
    }
}
console.log("break loop bilan:", count)

const matrix = [[3, 8], [12, 5], [7, 1]]
let found: number | null = null
let done = false

// Label o'rniga bayroq (flag): ichki sikl break qiladi, tashqi sikl bayroqni tekshiradi
for (const row of matrix) {
    for (const value of row) {
        if (value > 10) {
            found = value
            done = true
            break                   // faqat ichki sikldan
        }
    }
    if (done) break                 // tashqi sikl bayroqqa qarab chiqadi
}
console.log("10 dan katta birinchi qiymat:", found)

