type Order = { id: number; customer?: { email?: string }; total: number }
const orders: Order[] = [
    { id: 1, customer: { email: "a@mail.uz" }, total: 120 },
    { id: 2, total: 50 },
    { id: 3, customer: {}, total: 80 },
    { id: 4, customer: { email: "d@mail.uz" }, total: 0 },
    { id: 5, customer: { email: "e@mail.uz" }, total: 300 },
]

for (const order of orders) {
    // Guard clause'lar: noto'g'ri holatlar boshida continue bilan chiqariladi
    if (!order.customer) continue
    if (!order.customer.email) continue        // bu yerdan pastda email: string
    if (order.total === 0) continue
    console.log(`#${order.id}: ${order.customer.email.toUpperCase()} — ${order.total} so'm`)
}

