const primes: number[] = []
for (let n = 2; ; n++) {
    if (primes.length === 8) break
    let isPrime = true
    for (const p of primes) {
        if (p * p > n) break
        if (n % p === 0) { isPrime = false; break }
    }
    if (!isPrime) continue
    primes.push(n)
}
console.log(primes)

