function* naturals() {
    let n = 1
    while (true) yield n++          // cheksiz ketma-ketlik
}

// break bilan (klassik usul)
const firstEvens: number[] = []
for (const n of naturals()) {
    if (n % 2 !== 0) continue
    firstEvens.push(n)
    if (firstEvens.length === 3) break
}
console.log("break bilan:", firstEvens)

// Iterator helper'lar (Node 22+ / ES2025): take() kerakli miqdordan keyin o'zi to'xtaydi
console.log("take bilan:", naturals().filter(n => n % 2 === 0).take(3).toArray())
console.log("kvadratlar:", naturals().map(n => n * n).take(4).toArray())

const batches = [[1, 2, 3], [4, 0, 6], [7, 8, 9]]
let b = 0
const sums: number[] = []

batch: while (b < batches.length) {
    const items = batches[b++]          // hisoblagich ichki sikldan OLDIN oshiriladi
    let sum = 0
    for (const v of items) {
        if (v === 0) continue batch     // tashqi while'ning shartiga qaytadi — bu partiya tashlanadi
        sum += v
    }
    sums.push(sum)
}
console.log("0 bo'lmagan partiyalar yig'indisi:", sums)

const emails = ["ali@mail.uz", "vali@mail.uz", "ali@mail.uz", "soli@mail.uz", "vali@mail.uz"]
const seen = new Set<string>()
const unique: string[] = []

for (const email of emails) {
    if (seen.has(email)) continue   // takror — o'tkazib yuboramiz, tartib buzilmaydi
    seen.add(email)
    unique.push(email)
}
console.log(unique)
console.log("takrorlar:", emails.length - unique.length)
